from django.db import migrations, models


def backfill_apr(apps, schema_editor):
    """Disclose the APR on loans that were disbursed before it existed.

    Only loans with a schedule: their dates and instalments are known, so the rate
    is a fact about the contract. An application without one gets its figure from
    the quote when its agreement is printed, and a real one when it is disbursed.
    """
    from core.services.amortisation import annual_percentage_rate

    Loan = apps.get_model("core", "Loan")
    Instalment = apps.get_model("core", "Instalment")
    for loan in Loan.objects.filter(apr_pct__isnull=True, disbursement_date__isnull=False):
        rows = list(Instalment.objects.filter(loan_id=loan.pk).order_by("number")
                    .values_list("due_date", "principal_due", "interest_due"))
        if not rows:
            continue
        fees = loan.admin_fee + loan.insurance_fee + loan.other_charges
        loan.apr_pct = annual_percentage_rate(
            loan.principal - fees, [(due, p + i) for due, p, i in rows], loan.disbursement_date)
        loan.save(update_fields=["apr_pct"])


